@php
    $focusedYear = $c['method'] === 'year';
    $masterView=isset($c['builder']) && $c['builder']['view']==='master';
    $number = static fn ($value) => $value === null ? 'Not reported' : \App\Support\NumberFormatter::format($value, 2);
    $percentage = static fn ($value) => $value === null ? 'Awaiting result' : number_format($value, 2).'%';
    $statusLabels = ['ready'=>'Ready to compare','unmapped'=>'Needs KPI link','mapping_review'=>'Mapping review','definition_review'=>'Definition review','unit_mismatch'=>'Different units','missing_unit'=>'Unit unspecified','direction_review'=>'Direction review','missing_baseline'=>'Missing baseline result','missing_current'=>'Awaiting current results','incomplete_current'=>'Partial year','missing_target'=>'Target not set','department_review'=>'Accountable result needed'];
    $chartRows = $c['rows']->sortByDesc(fn ($r) => filled($r['kpiCode']))->unique('historicalId')->take(8)->values();
    $positive = $c['rows']->whereNotNull('delta')->sortByDesc('delta')->first();
    $negative = $c['rows']->whereNotNull('delta')->sortBy('delta')->first();
    $exportRecord = static fn ($r) => ['baselineYear'=>$c['baselineGregorianYear'],'baselineEfyYear'=>$c['historicalYear'],'currentYear'=>$c['currentGregorianYear'],'currentEfyYear'=>$c['currentEfyYear'],'sourceWorkbook'=>$c['import']?->original_filename,
        'rowType'=>isset($r['compositePair'])?'composite':'activity','summaryEligible'=>$r['summaryEligible']??true,
        'referenceWeightedScore'=>$r['compositePair']['reference']['rollup']['score']??null,'referenceAvailablePoints'=>$r['compositePair']['reference']['rollup']['weight']??null,
        'currentWeightedScore'=>$r['compositePair']['current']['rollup']['score']??null,'currentAvailablePoints'=>$r['compositePair']['current']['rollup']['weight']??null,
        'referenceWeight'=>null,'referenceContribution'=>null,'currentWeight'=>null,'currentContribution'=>null,'parentKpi'=>null,
    ]+\Illuminate\Support\Arr::only($r,['kpiCode','historicalCode','historicalDescription','currentCode','currentDescription','unit','currentUnit','department','historicalTarget','historicalActual','historicalAchievement','currentTarget','currentActual','currentAchievement','delta','actualChange','targetChange','readiness','reason','sourceRow']);
    $exportRows=$c['rows']->mapWithKeys(fn($r)=>['h:'.$r['historicalId'].'|'.($r['currentObjectiveId']?'o:'.$r['currentObjectiveId']:'')=>$exportRecord($r)]);
    foreach($c['rows'] as $parent){
        foreach($parent['compositePair']['componentPairs']??[] as $component){
            $a=$component['reference']; $d=$component['current']; $key=($a['id']??'').'|'.($d['id']??'');
            $extra=['referenceWeight'=>$a['weight']??null,'referenceContribution'=>$a['contribution']??null,'currentWeight'=>$d['weight']??null,'currentContribution'=>$d['contribution']??null,'parentKpi'=>$parent['kpiCode']];
            if($exportRows->has($key)){
                $exportRows->put($key,array_replace($exportRows->get($key),$extra));
            }else{
                $activity=['kpiCode'=>$a['kpi']??$d['kpi']??null,'historicalCode'=>$a['code']??null,'historicalDescription'=>$a['description']??null,'currentCode'=>$d['code']??null,'currentDescription'=>$d['description']??null,
                    'unit'=>$a['unit']??null,'currentUnit'=>$d['unit']??null,'department'=>$d['department']??$a['department']??null,'historicalTarget'=>$a['target']??null,'historicalActual'=>$a['actual']??null,'historicalAchievement'=>$a['achievement']??null,
                    'currentTarget'=>$d['target']??null,'currentActual'=>$d['actual']??null,'currentAchievement'=>$d['achievement']??null,'delta'=>$component['delta'],'actualChange'=>$component['actualChange'],'targetChange'=>$component['targetChange'],
                    'readiness'=>$component['status'],'reason'=>$component['reason'],'sourceRow'=>$a['sourceRow']??null];
                $exportRows->put($key,array_replace($exportRecord($activity),$extra,['rowType'=>'component']));
            }
        }
    }
    $exportRows=$exportRows->values();
